// Whether `subtype` is one of the subtypes above.
constexpr bool IsKnownCatalogObjectSubtype(CatalogObjectSubtype subtype) noexcept {
  for (const auto& s : kCatalogSubtypeIdentities)
    if (s.subtype == subtype) return true;
  return false;
}
// The fixed identity of a kind or a subtype; nullopt for one not listed.
constexpr std::optional<scratchbird::core::platform::Uuid> CatalogRecordKindIdentity(CatalogRecordKind kind) noexcept {
  for (const auto& k : kCatalogKindIdentities)
    if (k.kind == kind) return k.uuid;
  return std::nullopt;
}
constexpr std::optional<scratchbird::core::platform::Uuid> CatalogObjectSubtypeIdentity(CatalogObjectSubtype subtype) noexcept {
  for (const auto& s : kCatalogSubtypeIdentities)
    if (s.subtype == subtype) return s.uuid;
  return std::nullopt;
}
